+    for (const row of Object.values(settings.importers ?? {}))
+      for (const type of [
+        "dependencies",
+        "optionalDependencies",
+        "devDependencies",
+      ])
+        for (const name of policy.dependencies)
+          if (row[type]?.[name]) row[type][name].specifier = "<range>";
