+      const references = ["dependencies", "optionalDependencies"].flatMap(
+        (type) =>
+          Object.entries(row[type] ?? {})
+            .filter(([name]) => firstParty(name))
+            .map(([name, version]) => [type, name, walk(version, name)]),
